"""Fully observable, narrated M4 synthetic operator experience."""
from fastapi import Request
from fastapi.responses import HTMLResponse

import app as core
import m4_demo_cycle  # noqa: F401  # registers synthetic claim + narration endpoints


@core.app.get("/m4-operator-live", response_class=HTMLResponse)
def m4_operator_live(request: Request):
    user, redirect = core.login_required_redirect(request)
    if redirect:
        return redirect

    html = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>M4 Live Operator</title>
<style>
:root{--bg:#060806;--panel:#0b0f0b;--line:#263226;--ink:#edf5e8;--muted:#7d8979;--g:#a6ff2e;--good:#c8ff94}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% 12%,rgba(166,255,46,.07),transparent 30%),var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.shell{max-width:1380px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}.brand{letter-spacing:.16em;font-weight:800}.brand small{display:block;color:var(--muted);font:600 9px ui-monospace,monospace;margin-top:5px}.btn{border:1px solid var(--g);background:var(--g);color:#071007;padding:11px 14px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;text-decoration:none}.btn.alt{background:transparent;color:var(--ink);border-color:#465246}.hero{display:grid;grid-template-columns:1fr 330px;gap:38px;padding:38px 0 24px}.hero h1{font-size:clamp(42px,6vw,74px);line-height:.92;letter-spacing:-.05em;margin:8px 0 14px}.hero p{color:#aab2a6;max-width:780px;line-height:1.6}.m4{min-height:190px;border:1px solid var(--line);display:grid;place-items:center;background:radial-gradient(circle,rgba(166,255,46,.11),rgba(166,255,46,.018) 45%,transparent 72%);position:relative}.cell{width:66px;height:66px;border-radius:47% 53% 52% 48%;background:rgba(166,255,46,.17);box-shadow:0 0 28px rgba(166,255,46,.58),0 0 90px rgba(166,255,46,.17);animation:breathe 3.2s ease-in-out infinite}.m4.thinking .cell{animation-duration:.85s}.m4.acting .cell{box-shadow:0 0 48px rgba(166,255,46,.95),0 0 130px rgba(166,255,46,.36)}@keyframes breathe{50%{transform:scale(1.12) rotate(7deg)}}.m4 label{position:absolute;bottom:14px;color:#bfe89c;font:700 9px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:18px}.metric{border:1px solid var(--line);padding:12px;background:#0a0d0a}.metric b{font-size:20px}.metric small{display:block;color:var(--muted);font-size:9px;margin-top:4px}.revenue b{color:var(--g)}.grid{display:grid;grid-template-columns:290px 1fr 330px;gap:1px;background:var(--line);border:1px solid var(--line)}.pane{background:var(--panel);padding:20px;min-height:590px}.ey{color:var(--g);font:700 9px ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase}.pane h2{margin:8px 0 6px;font-size:21px}.sub{color:var(--muted);font-size:12px;line-height:1.5;margin-bottom:16px}.opening,.person,.node,.calendar-card{border:1px solid #2d392d;background:#0e140e;padding:12px;margin-bottom:8px}.opening.active,.person.focus,.calendar-card.flash{border-color:var(--g);box-shadow:inset 3px 0 0 var(--g)}.opening b,.person b,.calendar-card b{display:block;font-size:12px}.opening span,.person span,.calendar-card span{color:var(--muted);font:600 9px ui-monospace,monospace;display:block;margin-top:5px}.lanes{display:grid;grid-template-columns:1fr 1fr;gap:12px}.lane{border:1px dashed #303b30;min-height:205px;padding:11px}.lane h3{margin:0 0 10px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#9da996}.score{color:var(--g)!important}.tree{display:grid;gap:7px}.node{opacity:.34;transition:.3s}.node.active{opacity:1;border-color:var(--g);background:#101a0f}.node.done{opacity:.72}.node strong{font-size:11px}.node small{display:block;color:var(--muted);margin-top:4px}.log{margin-top:14px;border:1px solid #263026;background:#070a07;padding:13px;min-height:125px;white-space:pre-wrap;font:500 10px/1.65 ui-monospace,monospace;color:#b9c6b4}.offer-pop{position:fixed;right:24px;bottom:24px;width:min(360px,calc(100vw - 48px));background:#0d140c;border:1px solid var(--g);padding:18px;box-shadow:0 0 0 1px rgba(166,255,46,.08),0 24px 70px #000;z-index:30;display:none}.offer-pop.show{display:block;animation:pop .28s ease}.offer-pop h3{margin:0 0 6px}.offer-pop p{color:#a9b6a4;font-size:12px;line-height:1.5}.offer-state{color:var(--g);font:800 10px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase}.claim{margin-top:12px;border:1px solid var(--g);background:var(--g);padding:10px 12px;font-weight:900;cursor:pointer}.calendar{margin-top:14px}.calendar-card{transition:.35s}.calendar-card.flash{animation:flash 1.2s ease 2}@keyframes flash{50%{background:#1b2a11;box-shadow:0 0 34px rgba(166,255,46,.22)}}@keyframes pop{from{transform:translateY(16px);opacity:0}}.voice{font-size:10px;color:#9fb493;margin-top:8px}@media(max-width:980px){.grid,.hero{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.pane{min-height:auto}}
</style></head><body><div class="shell">
<div class="top"><div class="brand">EMPTY CHAIR<small>M4 // AUTONOMOUS RECOVERY</small></div><div style="display:flex;gap:8px"><button id="run" class="btn">Run full recovery</button><a class="btn alt" href="/demo">Demo home</a></div></div>
<section class="hero"><div><div class="ey">Observe → reason → offer → claim → book → learn</div><h1>Watch M4 close the loop.</h1><p>M4 narrates what she is doing, chooses the highest-value gap, ranks demand, sends a synthetic offer, receives a synthetic claim, places the booking on the calendar, and updates recovered revenue. No real customer is contacted.</p></div><div id="m4" class="m4"><div class="cell"></div><label id="m4state">observing shop state</label></div></section>
<div class="metrics"><div class="metric"><b id="mc">—</b><small>customers observed</small></div><div class="metric"><b id="mo">—</b><small>open gaps</small></div><div class="metric"><b id="mev">—</b><small>top expected value</small></div><div class="metric"><b id="mscore">—</b><small>M4 queue score</small></div><div class="metric revenue"><b id="revenue">$500</b><small>recovered revenue</small></div></div>
<section class="grid"><div class="pane"><div class="ey">01 // Inventory</div><h2>Open chair time</h2><div class="sub">M4 begins with perishable capacity.</div><div id="openings">Loading…</div><div class="calendar"><div class="ey">Calendar</div><div id="calendar"><div class="calendar-card"><b>Existing recovered booking</b><span>Alex Rivera · $500</span></div></div></div></div>
<div class="pane"><div class="ey">02 // Customer movement</div><h2>Population → shortlist → action</h2><div class="lanes"><div class="lane"><h3>Candidate pool</h3><div id="pool"></div></div><div class="lane"><h3>M4 shortlist</h3><div id="short"></div></div></div><div id="log" class="log">M4 // waiting for full recovery run</div><div id="voiceStatus" class="voice">Voice will use the configured M4 ElevenLabs voice when available.</div></div>
<div class="pane"><div class="ey">03 // Decision tree</div><h2>Observable reasoning</h2><div id="tree" class="tree"><div class="node"><strong>1. Opening value</strong><small>Find the most expensive perishable gap.</small></div><div class="node"><strong>2. Consent + eligibility</strong><small>Remove customers who should not be contacted.</small></div><div class="node"><strong>3. Artist affinity</strong><small>Weight demonstrated artist preference.</small></div><div class="node"><strong>4. Style fit</strong><small>Match tattoo preference to the opening.</small></div><div class="node"><strong>5. Budget fit</strong><small>Compare price with historical spend.</small></div><div class="node"><strong>6. Incremental uplift</strong><small>Estimate who is moved by this intervention.</small></div><div class="node"><strong>7. Confidence</strong><small>Weight the strength of available evidence.</small></div><div class="node"><strong>8. Sequential offer</strong><small>Send one best next action first.</small></div><div class="node"><strong>9. Outcome</strong><small>Claim, decline, expiry, or no response.</small></div><div class="node"><strong>10. Learn</strong><small>Store the result and improve the next decision.</small></div></div></div></section>
</div><div id="offer" class="offer-pop"><div class="offer-state" id="offerState">OFFER SENT</div><h3 id="offerName">Customer</h3><p id="offerText">Synthetic offer dispatched.</p><button id="claim" class="claim">Simulate customer claim</button></div>
<script>
(()=>{const run=document.getElementById('run'),m4=document.getElementById('m4'),m4state=document.getElementById('m4state'),openings=document.getElementById('openings'),pool=document.getElementById('pool'),short=document.getElementById('short'),log=document.getElementById('log'),offer=document.getElementById('offer'),claim=document.getElementById('claim'),calendar=document.getElementById('calendar'),voiceStatus=document.getElementById('voiceStatus');let data=null,selected=null,ranked=[],activeOffer=null,top=null;const sleep=ms=>new Promise(r=>setTimeout(r,ms));function state(s,mode='thinking'){m4.className='m4 '+mode;m4state.textContent=s;log.textContent+='\n'+s}function step(n){document.querySelectorAll('.node').forEach((x,i)=>{x.classList.toggle('active',i===n);if(i<n)x.classList.add('done')})}async function speak(key){try{const f=new FormData();f.append('key',key);const r=await fetch('/api/m4/operator/narrate',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(j.text)log.textContent+='\nM4: '+j.text;if(j.audio_base64){voiceStatus.textContent='M4 is speaking';await new Promise(resolve=>{const a=new Audio('data:audio/mpeg;base64,'+j.audio_base64);a.onended=resolve;a.onerror=resolve;a.play().catch(resolve)})}else{voiceStatus.textContent='M4 voice unavailable; narration shown as text.'}}catch(e){voiceStatus.textContent='M4 voice unavailable; narration shown as text.'}}async function load(reset=true){const r=await fetch('/api/m4/operator/status',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not load');if((!j.openings||!j.openings.length)&&j.synthetic&&reset){const rr=await fetch('/api/m4/operator/reset-synthetic',{method:'POST'});if(!rr.ok)throw Error('Could not reset synthetic demo');return load(false)}data=j;document.getElementById('mc').textContent=(j.dataset&&j.dataset.customers)||0;document.getElementById('mo').textContent=(j.openings||[]).length;openings.innerHTML='';(j.openings||[]).forEach(o=>{const d=document.createElement('div');d.className='opening';d.dataset.id=o.id;d.innerHTML=`<b>${o.style||'Open chair'} · $${Number(o.price||0).toLocaleString()}</b><span>${o.date} ${o.start_time}–${o.end_time||''} · ${o.artist_id}</span>`;openings.appendChild(d)});run.disabled=!j.openings||!j.openings.length}async function preview(o){const f=new FormData();f.append('opening_id',o.id);const r=await fetch('/api/m4/operator/preview',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error||'Preview failed');return j}function card(c){const d=document.createElement('div');d.className='person';d.dataset.id=c.customer_id;d.innerHTML=`<b>${c.name||c.customer_id}</b><span>booking ${Math.round(c.booking_probability*100)}% · uplift ${Math.round(c.incremental_uplift*100)}%</span><span class="score">queue ${c.queue_score} · EV $${Number(c.expected_value||0).toFixed(0)}</span>`;return d}async function animateRevenue(amount){const el=document.getElementById('revenue'),start=Number((el.textContent||'$0').replace(/[^0-9.]/g,''))||0,end=start+Number(amount||0),steps=28;for(let i=1;i<=steps;i++){el.textContent='$'+Math.round(start+(end-start)*(i/steps)).toLocaleString();await sleep(32)}}
claim.onclick=async()=>{if(!selected||!activeOffer)return;claim.disabled=true;document.getElementById('offerState').textContent='CLAIM RECEIVED';step(8);state(`${top.name||top.customer_id} claimed the opening`,'acting');await speak('claimed');const f=new FormData();f.append('opening_id',selected.id);f.append('offer_id',activeOffer);const r=await fetch('/api/m4/operator/demo-claim',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error||'Claim failed');document.getElementById('offerText').textContent='Claim converted to a confirmed synthetic booking.';const c=document.createElement('div');c.className='calendar-card flash';c.innerHTML=`<b>${j.customer_name} · ${j.style||'Tattoo'} · $${Number(j.amount).toLocaleString()}</b><span>${j.date} ${j.start_time}–${j.end_time||''} · ${j.artist_id}</span>`;calendar.prepend(c);await animateRevenue(j.amount);step(9);state(`Booking placed on calendar. $${Number(j.amount).toLocaleString()} recovered.`,'');await speak('learn');document.getElementById('offerState').textContent='CHAIR FILLED';claim.style.display='none';await sleep(1000);await load(false);run.disabled=false};
run.onclick=async()=>{run.disabled=true;offer.classList.remove('show');claim.style.display='block';claim.disabled=false;pool.innerHTML='';short.innerHTML='';log.textContent='M4 // autonomous recovery started';document.querySelectorAll('.node').forEach(x=>x.classList.remove('active','done'));try{if(!data||!data.openings||!data.openings.length)await load();step(0);state('Scanning open chair inventory');await speak('scan');selected=[...data.openings].sort((a,b)=>Number(b.price||0)-Number(a.price||0))[0];if(!selected)throw Error('No OPEN booking gap available.');document.querySelectorAll('.opening').forEach(x=>x.classList.toggle('active',x.dataset.id===selected.id));state(`Selected ${selected.style||'opening'} at $${Number(selected.price||0).toLocaleString()}`);step(1);await speak('filter');const p=await preview(selected);ranked=p.m4_top_candidates||[];document.getElementById('mc').textContent=p.consented_candidates;ranked.forEach(c=>pool.appendChild(card(c)));if(!ranked.length)throw Error('No eligible modeled customers returned.');await speak('fit');for(let s=2;s<=6;s++){step(s);const c=ranked[s-2];if(c){const el=pool.querySelector(`[data-id="${c.customer_id}"]`);if(el){el.classList.add('focus');await sleep(360);short.appendChild(el);el.classList.remove('focus')}}await sleep(260)}ranked.slice(5).forEach(c=>{const el=pool.querySelector(`[data-id="${c.customer_id}"]`);if(el)short.appendChild(el)});top=ranked[0];document.getElementById('mev').textContent='$'+Number(top.expected_value||0).toFixed(0);document.getElementById('mscore').textContent=top.queue_score;const te=short.querySelector(`[data-id="${top.customer_id}"]`);if(te)te.classList.add('focus');step(7);state(`Selected ${top.name||top.customer_id} as first contact`,'acting');await speak('choose');const f=new FormData();f.append('opening_id',selected.id);const r=await fetch('/api/m4/operator/activate',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error||'Activation failed');activeOffer=j.offer_id;document.getElementById('offerName').textContent=top.name||top.customer_id;document.getElementById('offerState').textContent='OFFER SENT';document.getElementById('offerText').textContent=`$${Number(selected.price||0).toLocaleString()} ${selected.style||'tattoo'} opening · synthetic recipient · no external delivery`;offer.classList.add('show');state('Offer sent. Waiting for customer behavior.','acting');await speak('sent')}catch(e){state('Interrupted: '+e.message,'');run.disabled=false}};load().catch(e=>{log.textContent=e.message;run.disabled=true})})();
</script></body></html>'''
    return HTMLResponse(html, headers={"Cache-Control": "no-store"})
